/* Local interaction prototype. All project data stays in this browser. */
(()=>{'use strict';
const C=Core,$=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),clone=C.clone;
const icon=(n,size=17)=>{const p={chev:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14M5 12h14',search:'m21 21-4.5-4.5M19 10.5a8.5 8.5 0 1 1-17 0 8.5 8.5 0 0 1 17 0',edit:'m16 3 5 5-13 13H3v-5L16 3ZM13 6l5 5',close:'m6 6 12 12M6 18 18 6',refresh:'M20 7v5h-5M4 17v-5h5M5.5 7a7 7 0 0 1 11.7-2L20 8M4 16l2.8 3A7 7 0 0 0 18.5 17',file:'M14 2H5v20h14V7l-5-5ZM14 2v5h5M8 12h8M8 16h8',calendar:'M4 5h16v16H4ZM8 2v6M16 2v6M4 11h16',archive:'M3 4h18v5H3ZM5 9v12h14V9M9 13h6',check:'m5 12 4 4L19 6',trash:'M3 6h18M8 6V3h8v3M6 6l1 15h10l1-15M10 10v7M14 10v7',up:'m6 15 6-6 6 6',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10M9 21h6',info:'M12 11v6M12 7v.1M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',cube:'m12 2 10 5v10l-10 5L2 17V7l10-5ZM2 7l10 5 10-5M12 12v10',download:'M12 2v13m-5-5 5 5 5-5M4 16v6h16v-6',settings:'M4 7h16M4 17h16M8 3v8M16 13v8',drag:'M4 9h16M4 15h16',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 1-2 4M12 18v.1M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM4 22a8 8 0 0 1 16 0',building:'M5 21V8l8-5v18M13 9h6v12M3 21h18M8 9v2M8 14v2M16 12v2M16 17v2',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7',arrow:'M5 12h14m-5-5 5 5-5 5'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p[n]||p.file}"/></svg>`;};
const esc=x=>String(x??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const btn=(a,label,cls='',attrs='')=>`<button type="button" data-action="${a}" class="btn ${cls}" ${attrs}>${label}</button>`;
const format=d=>d?d.split('-').reverse().join('.'):'—';
const badge=s=>`<span class="badge ${s==='Завершено'?'green':s==='В работе'?'blue':s==='Нет данных'?'muted':'gray'}">${s}</span>`;
let stored,legacy,savedTraits;try{stored=JSON.parse(localStorage.getItem('sbcde-prototype-v2'));legacy=JSON.parse(localStorage.getItem('sbcde-prototype-v1'));savedTraits=JSON.parse(localStorage.getItem('sbcde-prototype-traits-v1'));}catch{}
const TRAIT_CATALOG_REVISION='2026-11-05-construction-stage-bim-v4',TRAIT_CATALOG_REVISION_KEY='sbcde-prototype-traits-catalog-revision';
function seed(){const rows=C.demoRows(),ops=C.validateImport(rows,'2026-10-27',DEMO.traits).ops;const traits=clone(DEMO.traits);for(const t of traits)t.keys=t.keys.filter((k,i,a)=>a.findIndex(s=>C.normalize(s)===C.normalize(k))===i);const v1=clone(ops).slice(0,12).map((o,i)=>({...o,ff:null,fs:i<5&&o.fs&&o.fs<='2026-09-30'?o.fs:null}));const v2=clone(ops).slice(0,18).map(o=>({...o,ff:o.ff&&o.ff<='2026-10-14'?o.ff:null,fs:o.fs&&o.fs<='2026-10-14'?o.fs:null}));return {traits,models:clone(DEMO.models),versions:[{n:1,date:'2026-09-30',file:'КСП_Корпус-А_30.09.xlsx',sheet:'График',uploaded:'01.10.26, 10:42',archived:false,ops:v1},{n:2,date:'2026-10-14',file:'КСП_Корпус-А_14.10.xlsx',sheet:'График',uploaded:'15.10.26, 09:15',archived:true,ops:v2},{n:3,date:'2026-10-27',file:'КСП_Корпус-А_27.10.xlsx',sheet:'График',uploaded:'28.10.26, 11:32',archived:false,ops}],last:3,noticeTraits:false,noticeModels:true,ifcResult:C.groupModels(DEMO.models,traits)};}
if(!stored&&legacy&&!localStorage.getItem('sbcde-prototype-v1-migrated')){const base=seed();base.traits=clone(legacy.traits||base.traits);base.models=clone(legacy.models||base.models);base.ifcResult=C.groupModels(base.models,base.traits);stored=base;try{localStorage.setItem('sbcde-prototype-v2',JSON.stringify(stored));localStorage.setItem('sbcde-prototype-traits-v1',JSON.stringify(stored.traits));localStorage.setItem('sbcde-prototype-v1-migrated','1');}catch{}}
const WORK_STAGES=['Фундамент','Shell&Core','Фасады','Кровля','FitOut'];
const fresh=seed();let state=stored||fresh;let view='works',tab='schedule',role='admin',selected=null,expanded=new Set(),query='',filter='',onlyBim=false,workStage='all',sortKey='',sortAsc=true;
const savedCatalog=!C.validateTraits(savedTraits||[]).length&&savedTraits?.length?savedTraits:state.traits;
if(savedCatalog?.length){const needsCatalogMigration=localStorage.getItem(TRAIT_CATALOG_REVISION_KEY)!==TRAIT_CATALOG_REVISION;state.traits=needsCatalogMigration?C.mergeTraitCatalog(savedCatalog,fresh.traits):clone(savedCatalog);state.ifcResult=C.groupModels(state.models,state.traits);if(needsCatalogMigration)try{localStorage.setItem('sbcde-prototype-traits-v1',JSON.stringify(state.traits));localStorage.setItem(TRAIT_CATALOG_REVISION_KEY,TRAIT_CATALOG_REVISION);}catch{}}
if(!state.versions.some(v=>v.n===selected&&!v.archived))selected=current()?.n;
let popover=null,calendarMonth=null,modelQuery='',modal=null,importBook=null,importData=null,importResult=null,draftModels=null,traitDraft=null,traitIndex=0,mzIndex=0,step=1,traitQuery='',draftDate='',viewerLoad=null,modelProcessing=false,processSlide=0;
async function ensureViewer(){if(window.SBViewer)return window.SBViewer;if(!viewerLoad)viewerLoad=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/viewer.bundle.js?v=20261104-8';script.onload=()=>window.SBViewer?resolve(window.SBViewer):reject(new Error('Вьювер не зарегистрирован'));script.onerror=()=>reject(new Error('Не удалось загрузить локальный файл вьювера'));document.head.appendChild(script);}).catch(error=>{viewerLoad=null;throw error;});return viewerLoad;}
function current(){return state.versions.filter(v=>!v.archived).sort((a,b)=>b.n-a.n)[0];}
function chosen(){return state.versions.find(v=>v.n===selected&&!v.archived);}
const canProject=()=>role==='admin';
const canImport=canProject;
function persist(){try{const snapshot=clone(state);for(const model of snapshot.models)if(model.id.startsWith('ifc-'))model.elements=[];snapshot.ifcResult=C.groupModels(snapshot.models,snapshot.traits);const serialized=JSON.stringify(snapshot);localStorage.setItem('sbcde-prototype-v2',serialized);return localStorage.getItem('sbcde-prototype-v2')===serialized;}catch{toast('Не удалось сохранить данные в браузере.');return false;}}
function persistTraits(){try{const serialized=JSON.stringify(state.traits);localStorage.setItem('sbcde-prototype-traits-v1',serialized);return localStorage.getItem('sbcde-prototype-traits-v1')===serialized;}catch{return false;}}
let timer;function toast(msg){$('#toast').innerHTML=icon('check',15)+'<span>'+esc(msg)+'</span><button data-action="closetoast" aria-label="Закрыть уведомление">'+icon('close',12)+'</button>'; $('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function shell(){return `<header class="${view==='traits'?'system-header':''}"><div class="topbar"><a class="brand" href="#" data-action="home"><b>КСУП</b> BIM</a><button class="back" data-action="works">‹ &nbsp; К проектам</button><div class="project">${view==='traits'?'Настройки по системе':'Название проекта'} ${icon('info',15)}</div><div class="header-right">${view==='works'?`<button class="account" data-action="account"><span class="org-icon">${icon('building',25)}</span><span><small>Аккаунт</small><strong>ООО «Смарт …»</strong></span>${icon('down',12)}</button><button class="header-icon" data-action="traits" aria-label="Системные настройки" title="Системные настройки">${icon('settings',19)}</button><button class="header-icon" data-action="demo" aria-label="Сценарии макета" title="Сценарии макета">${icon('help',18)}</button><span class="header-messages">${icon('bell',19)}<b>10</b></span>`:''}<div class="account-anchor"><button class="avatar" data-action="account" aria-label="Роль в макете и настройки">${icon('user',23)}</button><div id="account-menu"></div></div></div></div>${view==='works'?`<nav aria-label="Разделы проекта"><span>Документация</span><span>Замечания</span><span>Согласования</span><span>МИР</span><span>MDR</span><span>BIM</span><button data-action="works" class="active">Работы</button><span>Объёмы</span><span>AI</span><button data-action="traits">Настройки</button><span>Реестр документов</span><span>Передачи</span><span>Участники</span></nav>`:''}</header>`;}
function accountMenu(){closePopover();popover='account';$('#account-menu').innerHTML=`<div class="floating-menu account-popover"><label>Роль в макете<select id="role" aria-label="Роль в макете"><option value="admin" ${role==='admin'?'selected':''}>Администратор</option><option value="user" ${role==='user'?'selected':''}>Пользователь</option></select></label>${canProject()?`<button data-action="traits">${icon('settings',15)} Системные настройки</button><button data-action="demo">${icon('grid',15)} Сценарии макета</button>`:''}</div>`;$('#role').onchange=e=>{role=e.target.value;closePopover();if(!canProject()&&view==='traits')view='works';render();};}
function closePopover(){popover=null;for(const b of document.querySelectorAll('.versions-anchor>button,.date-anchor>button'))b.setAttribute('aria-expanded','false');for(const id of ['version-menu','calendar-menu','account-menu','filter-menu']){const el=$('#'+id);if(el)el.innerHTML='';}}

function render(){closePopover();document.title=(view==='works'?'Работы':'Признаки')+' — КСУП BIM';$('#app').innerHTML=shell()+(view==='works'?works():traitsPage());bindSearch();}
function works(){const v=chosen(),stageOps=C.filterOperationsByStage(v?.ops||[],workStage,state.traits),stageModels=C.filterModelGroupsByStage(state.ifcResult.groups,workStage),linked=C.linkScheduleModels(stageOps,stageModels),groups=tab==='schedule'?linked.schedule:linked.models,bimCount=linked.schedule.filter(group=>group.count>0).length,stageModelCount=new Set(stageModels.flatMap(group=>group.models.map(model=>model.id))).size,stageElementCount=stageModels.reduce((sum,group)=>sum+group.count,0);let visible=groups.filter(g=>(g.code+' '+(g.ops?.map(o=>o.name).join(' ')||g.models?.map(m=>m.name).join(' '))).toLowerCase().includes(query.toLowerCase())&&(!filter||g.status===filter)&&(!onlyBim||g.count>0));if(sortKey){const sortValue=g=>sortKey==='ops'?(g.ops?.length??0):sortKey==='ifc'?(g.count??0):(g[sortKey]??'');visible.sort((a,b)=>String(sortValue(a)).localeCompare(String(sortValue(b)),'ru',{numeric:true})*(sortAsc?1:-1));}
const notice=state.noticeTraits||state.noticeModels;
const tip=[state.noticeTraits?'Изменились настройки признаков.':null,state.noticeModels?'Доступны новые версии выбранных моделей.':null,'Откройте «Настройки моделей».'].filter(Boolean).join(' ');
return `<main class="works-page" aria-label="Работы"><section class="registry"><div class="data-controls" role="toolbar" aria-label="Управление данными работ"><div class="segment"><button data-action="schedule" class="${tab==='schedule'?'selected':''}">График</button><button data-action="modeltab" class="${tab==='models'?'selected':''}">Модели</button></div><div class="control-anchor versions-anchor">${btn('versions',`<span class="toolbar-name">График СМР</span><b>${v?'v'+v.n:'—'}</b>${icon('down',12)}`,'version',`aria-label="Версии графика" aria-expanded="false"`)}<div id="version-menu"></div></div><div class="control-anchor date-anchor">${btn('date',`<span>${v?format(v.date):'Отчётная дата'}</span>${icon('edit',16)}`,'date',(!v?'disabled ':'')+`aria-label="Изменить отчётную дату" aria-expanded="false"`)}<div id="calendar-menu"></div></div><div class="spacer"></div>${notice?`<button class="notice" data-action="models" aria-label="Уведомления об актуальности моделей" data-tip="${esc(tip)}">${icon('bell',17)}<i></i></button>`:''}<button class="btn to-3d" data-action="open3d" title="${!v?'Нужен загруженный график СМР':!state.models.some(model=>model.selected!==null)?'Нужно выбрать хотя бы одну IFC-модель':'Открыть статусную модель СМР'}">Перейти в 3D</button>${canImport()?btn('import',icon('plus',15)+' График','primary'):''}${canProject()?btn('models',icon('plus',15)+' Модель','primary'):''}</div>
<div class="stage-switch" role="group" aria-label="Этап работ"><button data-action="stage" data-stage="all" class="${workStage==='all'?'selected':''}">Все этапы</button>${WORK_STAGES.map(stage=>`<button data-action="stage" data-stage="${esc(stage)}" class="${workStage===stage?'selected':''}">${esc(stage)}</button>`).join('')}</div>
<div class="registry-meta"><button data-action="bim" class="filter-pill ${onlyBim?'on':''}">Только с BIM: ${bimCount}</button><span class="load-meta">${tab==='schedule'?(v?`Дата загрузки: ${esc(v.uploaded.split(',')[0])} · Операции: ${stageOps.length}${workStage==='all'?'':` из ${v.ops.length}`}`:'График ещё не загружен'):`Моделей: ${stageModelCount}${workStage==='all'?'':` из ${state.models.filter(m=>m.selected!==null).length}`} · Элементов: ${stageElementCount}`}</span><div class="spacer"></div><div class="control-anchor filter-anchor"><button class="quiet-search ${query||filter?'has-filter':''}" data-action="filters" aria-label="Поиск и фильтр реестра" title="Поиск и фильтр">${icon('search',14)}</button><div id="filter-menu"></div></div>${btn('collapse','Свернуть все','link')}${btn('expand','Развернуть все','link')}</div>
<div class="table-scroll"><table class="register"><colgroup><col class="codecol"><col class="namecol"><col span="4" class="datecol"><col class="statuscol"><col span="2" class="numcol"></colgroup><thead><tr>${[['code','Код работы'],['','Наименование '+(tab==='schedule'?'операции':'модели')],['ps','Плановое начало'],['pf','Плановое окончание'],['fs','Факт начало'],['ff','Факт конец'],['status','Статус СМР'],['ops','Операции'],['ifc','IFC']].map(([k,l])=>`<th>${k?`<button data-action="sort" data-key="${k}">${l}<span class="sort ${sortKey===k?'sorted':''}">${sortKey===k?(sortAsc?'▴':'▾'):'⌃\n⌄'}</span></button>`:l}</th>`).join('')}</tr></thead><tbody>${visible.map(g=>groupRow(g)).join('')}</tbody></table>${!visible.length?empty(groups.length?'Ничего не найдено':tab==='schedule'?'Нет данных по графику':'Нет данных по моделям',groups.length?'Измените параметры поиска.':tab==='schedule'?'Загрузите график работ, чтобы сформировать реестр.':'Добавьте модели, чтобы сформировать реестр работ.',!groups.length&&canProject()?btn(tab==='schedule'?'import':'models',tab==='schedule'?'Загрузить график':'Добавить модели','primary'):''):''}</div></section></main>`;}
function filters(){closePopover();popover='filters';$('#filter-menu').innerHTML=`<div class="floating-menu filter-popover"><label>Поиск<input id="search" aria-label="Поиск в реестре" placeholder="Код работы, операция или модель" value="${esc(query)}"></label><label>Статус<select id="status-filter" aria-label="Фильтр статуса"><option value="">Все статусы</option>${['Не начато','В работе','Завершено','Нет данных'].map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select></label>${btn('applyfilters','Применить','primary')}</div>`;$('#search').focus();}

function groupRow(g){const open=expanded.has(g.code),model=tab==='models';const common=(o,op=false)=>`<td class="date-text">${format(o.ps)}</td><td class="date-text">${format(o.pf)}</td><td class="date-text">${format(o.fs)}</td><td class="date-text">${format(o.ff)}</td><td>${badge(o.status||(op?C.status(o):'Нет данных'))}</td>`;
return `<tr class="group ${open?'opened':''}"><td><button data-action="toggle" data-code="${esc(g.code)}" class="work-toggle"><span class="chevron ${open?'open':''}">${icon('chev',13)}</span><span>${esc(g.code)}</span></button></td><td class="subtle">—</td>${common(g)}<td class="numeric">${g.ops?.length??0}</td><td class="numeric">${g.count??0}</td></tr>`+(open?(model?g.models.map(m=>`<tr class="child"><td class="subtle indent">—</td><td><span class="model-name">${icon('file',14)}${esc(m.name)}</span></td>${common({})}<td class="numeric">—</td><td class="numeric">${m.count}</td></tr>`):g.ops.map(o=>`<tr class="child"><td class="subtle indent">—</td><td>${esc(o.name)}</td>${common(o,true)}<td class="subtle numeric">—</td><td class="subtle numeric">—</td></tr>`)).join(''):'');}
function empty(title,text,action=''){return `<div class="empty">${icon('file',35)}<h3>${title}</h3><p>${text}</p>${action}</div>`;}
function traitsPage(){return `<main class="system-page"><div class="settings-layout"><aside><div class="aside-label">Справочники</div><div class="aside-active">BIM</div><div class="aside-label">Доступы</div><button class="aside-collapse" data-action="collapseaside">‹‹ &nbsp; Свернуть</button></aside><section class="trait-content"><div class="settings-tab">Мониторинг (Признаки работ)</div><div class="search trait-search"><input id="trait-search" placeholder="Поиск" aria-label="Поиск признака" value="${esc(traitQuery)}">${icon('search',17)}</div><p class="hint settings-hint">${icon('info',13)} Признаки работ и их соответствия между исходными и целевыми значениями</p><div class="trait-cards">${state.traits.filter(t=>t.name.toLowerCase().includes(traitQuery.toLowerCase())).map(t=>`<article class="trait-card ${t.derivedFrom?'derived-trait':''}"><div class="card-heading"><h3>${esc(t.name)}${t.derivedFrom?'<small class="derived-badge">Производный</small>':''}</h3><button class="icon-button" data-action="edittrait" data-id="${t.id}" aria-label="Редактировать ${esc(t.name)}" title="Редактировать">${icon('edit',16)}</button></div><details><summary>${t.derivedFrom?'Источник':'Где искать'} · ${t.keys.length} ${icon('down',11)}</summary><ol class="preview-list">${t.keys.map(k=>`<li>${esc(k)}</li>`).join('')}</ol></details><details><summary>Значения · ${t.values.length} ${icon('down',11)}</summary><ul class="preview-list">${t.values.map(v=>`<li>${esc(v.name)}${t.derivedFrom?` <small>${v.aliases.length} КФО</small>`:''}</li>`).join('')}</ul></details></article>`).join('')}</div></section></div></main>`;}

function bindSearch(){if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};if($('#status-filter'))$('#status-filter').onchange=e=>{filter=e.target.value;render();};if($('#trait-search'))$('#trait-search').oninput=e=>{const pos=e.target.selectionStart;traitQuery=e.target.value;render();$('#trait-search').focus();$('#trait-search').setSelectionRange(pos,pos);};}
function showModal(kind,body,title,footer='',wide=false){closePopover();modal=kind;$('#overlay').innerHTML=`<div class="scrim"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal modal-${kind} ${wide?'wide':''}"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close',14)}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('#overlay button:not(:disabled)')?.focus(),0);}

function close(){closePopover();modal=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');}
function versions(){if(popover==='versions'){closePopover();return;}closePopover();popover='versions';$('.versions-anchor>button').setAttribute('aria-expanded','true');const active=current();$('#version-menu').innerHTML=`<div class="floating-menu version-list" role="menu" aria-label="Версии графика">${[...state.versions].sort((a,b)=>b.n-a.n).map(v=>`<div class="version-row ${v.archived?'archived':''} ${v.n===selected?'chosen-version':''}"><button data-action="chooseversion" data-n="${v.n}" class="version-choice" ${v.archived?'disabled':''}><span class="version-title">График СМР</span><span class="version-number">v${v.n}</span>${v.archived?'<span class="badge gray">Архивная</span>':v.n===active?.n?'<span class="badge green">Актуальная</span>':''}</button>${canProject()?btn(v.archived?'restore':'archive',icon(v.archived?'refresh':'trash',14),'icon-button',`data-n="${v.n}" aria-label="${v.archived?'Восстановить':'Архивировать'} v${v.n}" title="Прототип: ${v.archived?'восстановление':'архивирование'} версии. В MVP этого действия не будет."`):''}</div>`).join('')||'<p class="hint">Нет загруженных графиков</p>'}</div>`;}

function editDate(){if(popover==='date'){closePopover();return;}const v=chosen();if(!v)return;closePopover();popover='date';$('.date-anchor>button').setAttribute('aria-expanded','true');draftDate=v.date;calendarMonth=v.date.slice(0,7);drawCalendar();}
function drawCalendar(){const v=chosen(),max=C.max(v.ops.flatMap(o=>[o.fs,o.ff])),base=new Date(calendarMonth+'-01T00:00:00Z'),y=base.getUTCFullYear(),m=base.getUTCMonth(),offset=(base.getUTCDay()+6)%7;const title=base.toLocaleDateString('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'}).replace(' г.','');const days=Array.from({length:42},(_,i)=>{const d=new Date(Date.UTC(y,m,i-offset+1)),iso=d.toISOString().slice(0,10);return `<button data-action="pickdate" data-date="${iso}" class="calendar-day ${d.getUTCMonth()!==m?'other-month':''} ${iso===draftDate?'picked':''}" ${max&&iso<max?'disabled':''}>${d.getUTCDate()}</button>`;}).join('');$('#calendar-menu').innerHTML=`<div class="floating-menu calendar-popover" role="dialog" aria-label="Отчётная дата"><div class="calendar-heading"><button data-action="calprevyear" aria-label="Предыдущий год">«</button><button data-action="calprev" aria-label="Предыдущий месяц">‹</button><strong>${title}</strong><button data-action="calnext" aria-label="Следующий месяц">›</button><button data-action="calnextyear" aria-label="Следующий год">»</button></div><div class="calendar-week">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(s=>`<span>${s}</span>`).join('')}</div><div class="calendar-grid">${days}</div><label class="calendar-direct"><input type="date" id="new-date" aria-label="Отчётная дата" value="${draftDate}" ${max?'min="'+max+'"':''} ${!canProject()?'disabled':''}></label><p class="error-text" id="date-error"></p>${btn('savedate','Сохранить','primary',!canProject()?'disabled':'')}</div>`;$('#new-date').oninput=e=>{draftDate=e.target.value;const bad=!draftDate||max&&draftDate<max;$('#date-error').textContent=bad?'Дата должна быть не раньше '+format(max):'';$('[data-action="savedate"]').disabled=bad;};}

function importModal(){if(!canImport())return;importBook=null;importData=null;importResult=null;showModal('import',`<div class="import-info">${icon('info',14)} Загрузите файл с расширением .xlsx</div><label class="dropzone" id="dropzone"><span class="upload-empty"><span>Перетащите файл в эту область для загрузки или</span><b>Выберите файл</b></span><strong class="uploaded-name"></strong><input id="upload" type="file" accept=".xlsx" hidden></label><p class="error-text" id="file-error"></p><label class="import-sheet-label" hidden>Лист импорта<select id="import-sheet" disabled><option>Выберите лист</option></select></label><label>Отчётная дата<input type="date" id="import-date" disabled></label><p class="hint" id="import-hint" hidden></p>`,'Импорт графика',btn('close','Отменить')+btn('runimport','Импортировать','primary','disabled'));
$('#upload').onchange=e=>loadFile(e.target.files[0]);$('#dropzone').ondragover=e=>{e.preventDefault();$('#dropzone').classList.add('dragover');};$('#dropzone').ondragleave=()=>$('#dropzone').classList.remove('dragover');$('#dropzone').ondrop=e=>{e.preventDefault();loadFile(e.dataTransfer.files[0]);};$('#import-date').oninput=enableImport;}
function fileLoaded(){const dz=$('#dropzone');dz.classList.add('has-file');$('.import-sheet-label').hidden=false;}
async function loadFile(file){if(!file)return;$('#file-error').textContent='';try{importBook=await XlsxReader.open(file);importBook.filename=file.name;$('#dropzone strong').textContent=file.name;fileLoaded();const select=$('#import-sheet');select.disabled=false;select.innerHTML=importBook.names.map((n,i)=>`<option value="${i}">${esc(n)}</option>`).join('');select.onchange=readSheet;await readSheet();}catch(e){$('#file-error').textContent=e.message||'Не удалось прочитать файл.';importData=null;enableImport();}}
async function readSheet(){try{importData=await importBook.sheet(Number($('#import-sheet').value));$('#import-date').disabled=false;$('#import-date').value=importData.date||'';$('#import-hint').textContent=importData.date?'Отчётная дата считана. При необходимости измените её.':'Укажите корректную отчётную дату вручную.';enableImport();}catch(e){importData=null;$('#file-error').textContent=e.message;enableImport();}}
function enableImport(){const b=$('[data-action="runimport"]');if(b)b.disabled=!importData||!$('#import-date')?.value;}
function demoLoad(kind='partial'){importBook={filename:'КСП_демонстрационный.xlsx',names:['График']};importData={rows:C.demoRows(),date:'2026-10-27'};if(kind==='partial')importData.rows[4].name='';if(kind==='fatal')importData.rows[1].kfo='НЕИЗВЕСТНЫЙ КФО';$('#dropzone strong').textContent=importBook.filename;fileLoaded();$('#import-sheet').innerHTML='<option value="0">График</option>';$('#import-sheet').disabled=false;$('#import-sheet').onchange=null;$('#import-date').disabled=false;$('#import-date').value=importData.date;$('#import-hint').textContent='Демонстрационный график готов к проверке.';enableImport();}
function runImport(){if(!canImport()||!importData||!$('#import-date').value)return;const d=$('#import-date').value;const result=C.validateImport(importData.rows,d,state.traits);importResult=result;let version;if(result.loaded){version=++state.last;state.versions.push({n:version,date:d,file:importBook.filename,sheet:importBook.names[Number($('#import-sheet').value)]||'График',uploaded:new Date().toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'}),archived:false,ops:clone(result.ops)});selected=version;tab='schedule';expanded.clear();persist();render();}
showModal('import-result',`<div class="import-alert ${result.result}">${icon(result.result==='error'?'close':result.result==='partial'?'info':'check',16)}<div><strong>${result.result==='error'?'Импорт не выполнен':result.result==='partial'?'Импорт выполнен частично':'Импорт выполнен'}</strong>${result.result==='success'?`<p>Загружено ${result.loaded} операций.</p>`:`<p>Всего операций: ${result.total}<br>Загружено: ${result.loaded}<br>Не загружено: ${result.rejected}</p>${btn('downloadreport','Скачать отчёт','report-link')}`}</div></div><div class="result-file">${icon('file',16)}<span>${esc(importBook.filename)}</span></div>`,'Импорт графика');}
async function syncIfcCatalog(){try{const response=await fetch('/api/models',{cache:'no-store'});if(!response.ok)return false;const data=await response.json(),existing=new Map(state.models.map(model=>[model.id,model])),disk=data.models.map(model=>{const old=existing.get(model.id),selected=old&&model.versions.some(version=>version.n===old.selected)?old.selected:null;return {...model,selected,elements:selected===old?.selected?old.elements||[]:[],processedVersion:selected===old?.selected?old.processedVersion??null:null,sourceHash:selected===old?.selected?old.sourceHash??null:null,schema:old?.schema??null,error:old?.error??null};});state.models=disk;state.ifcResult=C.groupModels(state.models,state.traits);return true;}catch{return false;}}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function processIfcSelections(models,selections,onProgress){if(!selections.length)return true;const start=await fetch('/api/models/process/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({selections})});if(!start.ok)return false;const started=await start.json();let data;while(true){await wait(500);const response=await fetch(`/api/models/process/${encodeURIComponent(started.jobId)}`,{cache:'no-store'});if(!response.ok)return false;data=await response.json();onProgress?.(data);if(data.status==='error')return false;if(data.status==='done')break;}for(const result of data.results||[]){const model=models.find(candidate=>candidate.id===result.id);if(!model)continue;model.elements=result.elements||[];model.sourceHash=result.sourceHash||null;model.schema=result.schema||null;model.error=result.error||null;model.processedVersion=result.processed?result.version:null;const version=model.versions.find(candidate=>candidate.n===result.version);if(version&&result.processed)version.processed=true;}return data.results?.length===selections.length&&data.results.every(result=>result.processed);}
function modelProcessingUi(){modelProcessing=true;const body=$('.modal-models .modal-body'),controls=$$('.modal-models button,.modal-models input,.modal-models select');controls.forEach(control=>control.disabled=true);const started=Date.now(),panel=document.createElement('div');panel.className='model-processing';panel.innerHTML=`<div class="model-processing-card"><span class="model-processing-spinner"></span><strong id="model-processing-title">Подготавливаем IFC-модель</strong><p id="model-processing-file">Запускаем обработку…</p><div class="model-processing-track"><i id="model-processing-bar"></i></div><div class="model-processing-meta"><span id="model-processing-count">Определяем количество элементов</span><span id="model-processing-time">0 сек</span></div><small>Файл обрабатывается локально и никуда не загружается. Большая модель может занять несколько минут.</small></div>`;body.appendChild(panel);const ticker=setInterval(()=>{const time=$('#model-processing-time');if(time)time.textContent=`${Math.floor((Date.now()-started)/1000)} сек`;},1000);return {update(job){const p=job.progress||{},percent=p.total?Math.round(p.completed/p.total*100):0,stage=p.stage==='hashing'?'Проверяем SHA-256 модели':p.stage==='cached'?'Берём готовые данные из кеша':p.stage==='opening'?'Открываем IFC-файл':p.stage==='properties'?'Считываем свойства элементов':'Подготавливаем обработку';$('#model-processing-title').textContent=`${stage} · ${p.modelIndex||1} из ${p.modelTotal||1}`;$('#model-processing-file').textContent=p.file||'IFC-модель';$('#model-processing-count').textContent=p.total?`${p.completed.toLocaleString('ru-RU')} из ${p.total.toLocaleString('ru-RU')} элементов · ${percent}%`:'Определяем количество элементов';$('#model-processing-bar').style.width=`${percent}%`;},finish(){clearInterval(ticker);modelProcessing=false;}};}
async function hydrateSelectedIfc(){const selections=state.models.filter(model=>model.id.startsWith('ifc-')&&model.selected!==null&&!model.elements.length).map(model=>({id:model.id,version:model.selected}));if(!selections.length)return;await processIfcSelections(state.models,selections);state.ifcResult=C.groupModels(state.models,state.traits);render();}
async function openViewer(){const version=chosen(),models=state.models.filter(model=>model.id.startsWith('ifc-')&&model.selected!==null);if(!version){toast('Для перехода в 3D сначала загрузите график СМР');return;}if(!models.length){toast('Для перехода в 3D выберите хотя бы одну IFC-модель');return;}const button=$('[data-action="open3d"]');if(button){button.disabled=true;button.textContent='Открываем 3D…';}try{await ensureViewer();}catch(error){console.error('Не удалось запустить 3D-вьювер',error);render();toast(`Не удалось запустить 3D-вьювер: ${error?.message||'неизвестная ошибка'}`);return;}const pending=models.filter(model=>model.processedVersion!==model.selected||!model.elements.length).map(model=>({id:model.id,version:model.selected}));if(pending.length){toast('Читаем свойства выбранных IFC-моделей для отображения в браузере…');if(!await processIfcSelections(state.models,pending)){render();toast('Не удалось прочитать свойства одной из IFC-моделей');return;}state.ifcResult=C.groupModels(state.models,state.traits);}window.SBViewer.open({version:clone(version),models:clone(models),traits:clone(state.traits)});}
async function modelSettings(){modelQuery='';if(!await syncIfcCatalog())toast('Не удалось прочитать папку IFC моделей');draftModels=clone(state.models);modelModal();}
async function clearPrototypeCache(){try{const response=await fetch('/api/prototype/cache/clear',{method:'POST'}),data=await response.json();if(!response.ok)throw new Error(data.error||'Не удалось очистить кеш');for(const model of state.models.filter(model=>model.id.startsWith('ifc-'))){model.elements=[];model.processedVersion=null;model.sourceHash=null;}state.ifcResult=C.groupModels(state.models,state.traits);persist();close();render();toast(`Прототипный кеш очищен: ${data.cleared.properties+data.cleared.geometry} файлов`);}catch(error){toast(error.message||'Не удалось очистить кеш');}}
function modelModal(){const dirty=JSON.stringify(draftModels.map(m=>m.selected))!==JSON.stringify(state.models.map(m=>m.selected));
showModal('models',`<div class="models-search search"><input id="model-search" value="${esc(modelQuery)}" placeholder="Поиск" aria-label="Поиск модели">${icon('search',17)}</div><div class="model-table-wrap"><table class="model-table"><thead><tr><th></th>${['Наименование файла','Версия','Связанные папки','Автор','Дата','Размер'].map(x=>`<th>${x}<span class="sort">⌃\n⌄</span></th>`).join('')}</tr></thead><tbody>${[...draftModels].sort((a,b)=>Number(b.selected!==null)-Number(a.selected!==null)).map(m=>{const processed=m.versions.filter(v=>v.processed),choice=m.selected??processed[0]?.n,outdated=m.selected!==null&&m.selected<Math.max(...m.versions.map(v=>v.n));return `<tr data-model-row="${esc(m.name.toLowerCase())}" ${!m.name.toLowerCase().includes(modelQuery.toLowerCase())?'hidden':''} class="${!processed.length?'unprocessed':''}"><td><input type="checkbox" aria-label="Выбрать ${esc(m.name)}" data-model="${m.id}" ${m.selected!==null?'checked':''} ${!processed.length||!canProject()?'disabled':''}></td><td><span class="model-name">${icon('file',17)} ${esc(m.name)}</span>${!processed.length?'<span class="model-caption">Обрабатывается</span>':''}</td><td><div class="version-cell"><span class="model-version-number">v${choice??m.versions[0].n}</span><span class="badge ${outdated?'amber':'green'}">${!processed.length?'Обработка':outdated?'Неактуально':'Актуальная'}</span><select aria-label="Версия ${esc(m.name)}" data-model-version="${m.id}" ${!canProject()||!processed.length?'disabled':''}>${m.versions.map(v=>`<option value="${v.n}" ${choice===v.n?'selected':''} ${!v.processed?'disabled':''}>v${v.n}${!v.processed?' · Обрабатывается':''}</option>`).join('')}</select>${icon('down',11)}</div></td><td><span class="folder-path" title="Название проекта / Модели">Название проекта / Модели …</span></td><td><span class="author"><span class="mini-avatar">${m.author.split(' ').map(n=>n[0]).join('')}</span><span>${esc(m.author)}<small>Проектная организация</small></span></span></td><td class="model-date">${m.date}</td><td>${m.size}</td></tr>`;}).join('')}</tbody></table></div>`,'Настройка моделей',(canProject()?btn('refreshmodels',icon('refresh',14)+' Обновить BIM','left',(!draftModels.some(m=>m.selected!==null)?'disabled ':'')+'title="Проверить SHA-256 выбранных IFC-моделей и пересчитать работы"'):'')+btn('close','Отменить')+(canProject()?btn('savemodels','Добавить','primary',!dirty?'disabled':''):''),true);
if(canProject()){const clearButton=document.createElement('button');clearButton.type='button';clearButton.className='btn prototype-action';clearButton.dataset.action='clearcache';clearButton.textContent='Очистить хэш';clearButton.title='Прототип: очистить SHA-256 и кеш обработки IFC. В MVP этой кнопки не будет.';clearButton.setAttribute('aria-label','Очистить прототипный хэш и кеш IFC');$('.modal-models .modal-footer')?.prepend(clearButton);}
$('#model-search').oninput=e=>{modelQuery=e.target.value;for(const row of document.querySelectorAll('[data-model-row]'))row.hidden=!row.dataset.modelRow.includes(e.target.value.toLowerCase());};document.querySelectorAll('[data-model]').forEach(el=>el.onchange=()=>{const m=draftModels.find(m=>m.id===el.dataset.model);m.selected=el.checked?m.versions.find(v=>v.processed).n:null;modelModal();});document.querySelectorAll('[data-model-version]').forEach(el=>el.onchange=()=>{const m=draftModels.find(m=>m.id===el.dataset.modelVersion);m.selected=Number(el.value);modelModal();});}

async function applyModels(){if(!canProject()||modelProcessing)return;const previous=new Map(state.models.map(model=>[model.id,model])),selections=draftModels.filter(model=>model.id.startsWith('ifc-')&&model.selected!==null&&(previous.get(model.id)?.selected!==model.selected||model.processedVersion!==model.selected)).map(model=>({id:model.id,version:model.selected})),progress=modelProcessingUi();let success=false;try{success=await processIfcSelections(draftModels,selections,job=>progress.update(job));}catch(error){console.error('Ошибка обработки IFC',error);}progress.finish();if(!success){modelModal();toast('Не удалось обработать одну из выбранных версий IFC. Можно повторить попытку.');return;}state.models=clone(draftModels);state.ifcResult=C.groupModels(state.models,state.traits);state.noticeTraits=false;state.noticeModels=state.models.some(m=>m.selected!==null&&m.selected<Math.max(...m.versions.map(v=>v.n)));expanded.clear();tab='models';view='works';persist();render();showModal('model-result',`<div class="result-hero success"><span class="result-icon">${icon('check',25)}</span><div><h3>Работы сформированы</h3><p>Обработаны только новые и изменённые версии моделей.</p></div></div><table class="summary-table"><thead><tr><th>Модель</th><th>Всего элементов</th><th>С распознанным КФО</th><th>Без распознанного КФО</th></tr></thead><tbody>${state.ifcResult.summary.map(m=>`<tr><td>${esc(m.name)}</td><td>${m.total}</td><td>${m.read}</td><td>${m.unread}</td></tr>`).join('')}</tbody></table>`,'Результат обработки моделей',btn('close','К реестру','primary'),true);}
async function refreshModels(){if(!canProject()||modelProcessing)return;const selected=draftModels.filter(model=>model.id.startsWith('ifc-')&&model.selected!==null),previousHashes=new Map(selected.map(model=>[model.id,model.sourceHash])),selections=selected.map(model=>({id:model.id,version:model.selected,forceHash:true}));if(!selections.length)return;const progress=modelProcessingUi();let success=false;try{success=await processIfcSelections(draftModels,selections,job=>progress.update(job));}catch(error){console.error('Ошибка обновления IFC',error);}progress.finish();if(!success){modelModal();toast('Не удалось обновить одну из выбранных IFC-моделей. Можно повторить попытку.');return;}const changed=selected.filter(model=>previousHashes.get(model.id)&&previousHashes.get(model.id)!==model.sourceHash).length;state.models=clone(draftModels);state.ifcResult=C.groupModels(state.models,state.traits);state.noticeTraits=false;state.noticeModels=state.models.some(model=>model.selected!==null&&model.selected<Math.max(...model.versions.map(version=>version.n)));expanded.clear();tab='models';persist();render();showModal('model-result',`<div class="result-hero success"><span class="result-icon">${icon('refresh',25)}</span><div><h3>Работы пересчитаны</h3><p>Проверено моделей: ${selections.length}. Изменилось содержимое: ${changed}. ${changed?'Изменённые IFC разобраны заново.':'IFC не изменились, свойства взяты из кеша; маппинг работ выполнен повторно.'}</p></div></div><table class="summary-table"><thead><tr><th>Модель</th><th>Всего элементов</th><th>С распознанным КФО</th><th>Без распознанного КФО</th></tr></thead><tbody>${state.ifcResult.summary.map(model=>`<tr><td>${esc(model.name)}</td><td>${model.total}</td><td>${model.read}</td><td>${model.unread}</td></tr>`).join('')}</tbody></table>`,'Результат обновления BIM',btn('close','К реестру','primary'),true);}
function startTrait(id){traitIndex=state.traits.findIndex(t=>t.id===id);traitDraft=clone(state.traits);step=1;mzIndex=0;editTrait();}
function editTrait(){const t=traitDraft[traitIndex],v=t.values[mzIndex],errors=C.validateTraits(traitDraft);showModal('trait',`<div class="steps"><button data-action="traitstep1" class="${step===1?'current':'complete'}"><i>${step===1?'1':icon('check',12)}</i> Основные данные</button><span class="${step===2?'complete':''}"></span><button data-action="traitstep2" class="${step===2?'current':''}"><i>2</i> Настройка значений</button></div>${step===1?`<div class="trait-basics"><label class="trait-name-label">Наименование*<small>${t.name.length} / 128</small><input value="${esc(t.name)}" disabled></label><div class="keys-panel"><h3>Где искать</h3><p class="panel-description">Атрибуты маппинга. Система проверяет параметры по приоритету снизу вверх.</p><div class="key-list">${t.keys.map((k,i)=>`<div class="key-row" draggable="true" data-keyrow="${i}"><span class="drag-handle" title="Перетащите для изменения порядка">${icon('drag',14)}</span><span class="index">№${i+1}</span><input data-keyinput="${i}" value="${esc(k)}" aria-label="Ключ признака ${i+1}"><div class="key-moves"><button class="icon-button" data-action="key-up" data-i="${i}" ${i===0?'disabled':''} aria-label="Переместить ключ ${i+1} вверх">${icon('up',12)}</button><button class="icon-button" data-action="key-down" data-i="${i}" ${i===t.keys.length-1?'disabled':''} aria-label="Переместить ключ ${i+1} вниз">${icon('down',12)}</button></div><button class="icon-button" data-action="delkey" data-i="${i}" aria-label="Удалить ключ ${i+1}">${icon('trash',15)}</button></div>`).join('')}<div class="key-row new-key"><span class="drag-handle">${icon('drag',14)}</span><span class="index">№${t.keys.length+1}</span><input id="newkey" placeholder="Введите атрибут" aria-label="Новый ключ признака"><button class="icon-button" data-action="addkey" aria-label="Добавить ключ">${icon('plus',16)}</button></div></div><div class="validation" id="trait-errors"></div></div></div>`:`<div class="values-editor"><div class="values-list"><div class="label-row"><b>Значение в системе</b>${btn('addmz',icon('plus',13)+' Добавить','link')}</div><div class="mz-scroll">${t.values.map((m,i)=>`<div class="mz-row ${i===mzIndex?'active':''}"><button data-action="selectmz" data-i="${i}">${esc(m.name)||'<span class="subtle">Новое значение</span>'}</button><button class="icon-button" data-action="delmz" data-i="${i}" aria-label="Удалить ${esc(m.name)}">${icon('trash',15)}</button></div>`).join('')}</div><div class="validation" id="trait-errors"></div></div><div class="value-detail"><h3>Настройка значения</h3>${v?`<label>Наименование значения<input id="mzname" placeholder="Введите наименование значения" value="${esc(v.name)}"></label><div class="alias-label">Допустимые варианты</div><div class="alias-scroll">${v.aliases.map((a,i)=>`<div class="alias-row"><input data-aliasinput="${i}" value="${esc(a)}" aria-label="Допустимый вариант ${i+1}"><button class="icon-button" data-action="delalias" data-i="${i}" aria-label="Удалить вариант ${i+1}">${icon('trash',15)}</button></div>`).join('')}<div class="alias-row"><input id="newalias" placeholder="Введите допустимое значение" aria-label="Новый допустимый вариант"><button class="icon-button" data-action="addalias" aria-label="Добавить допустимый вариант">${icon('plus',16)}</button></div></div>`:''}</div></div>`}`,'Редактирование признака',step===1?btn('close','Отменить')+btn('traitstep2','Настроить значения','primary'):btn('traitstep1','Назад')+btn('savetrait','Сохранить','primary',errors.length?'disabled':''),true);
const priorityHint=$('.panel-description');if(priorityHint?.textContent.includes('приоритету'))priorityHint.textContent='Атрибуты маппинга. Система проверяет параметры по приоритету сверху вниз.';
const valuesHeading=$('.values-list .label-row b');if(valuesHeading)valuesHeading.textContent=`Значения в системе · ${t.values.length}`;
document.querySelectorAll('[data-keyinput]').forEach(el=>{if(t.derivedFrom)el.disabled=true;el.oninput=()=>{if(t.derivedFrom)return;t.keys[Number(el.dataset.keyinput)]=el.value;validateTraitUi();};});if(t.derivedFrom)document.querySelectorAll('[data-action="addkey"],[data-action="delkey"],[data-action="key-up"],[data-action="key-down"],#newkey').forEach(el=>el.disabled=true);let dragIndex;document.querySelectorAll('[data-keyrow]').forEach(el=>{el.ondragstart=e=>{if(t.derivedFrom||e.target.tagName==='INPUT'){e.preventDefault();return;}dragIndex=Number(el.dataset.keyrow);el.classList.add('dragging');};el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();const j=Number(el.dataset.keyrow);if(Number.isInteger(dragIndex)&&dragIndex!==j){const [key]=t.keys.splice(dragIndex,1);t.keys.splice(j,0,key);editTrait();}};el.ondragend=()=>el.classList.remove('dragging');});if($('#mzname'))$('#mzname').oninput=e=>{v.name=e.target.value;const row=document.querySelector('.mz-row.active > button');if(row)row.textContent=v.name||'Новое значение';validateTraitUi();};document.querySelectorAll('[data-aliasinput]').forEach(el=>el.oninput=()=>{v.aliases[Number(el.dataset.aliasinput)]=el.value;validateTraitUi();});for(const [id,action] of [['newkey','addkey'],['newalias','addalias']]){const el=$('#'+id);if(el)el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$(`[data-action="${action}"]`).click();}};}validateTraitUi();}

function validateTraitUi(){const errors=C.validateTraits(traitDraft),visible=step===1?errors.filter(s=>s.toLowerCase().includes('ключ')):errors;$('#trait-errors').innerHTML=visible.slice(0,3).map(e=>`<p>${esc(e)}</p>`).join('');const save=$('[data-action="savetrait"]');if(save)save.disabled=!!errors.length;const next=$('.modal-footer [data-action="traitstep2"]');if(next)next.disabled=!!visible.length;}
function commitPendingKey(){const input=$('#newkey'),value=input?.value.trim();if(!value)return false;traitDraft[traitIndex].keys.push(value);input.value='';return true;}
function commitPendingAlias(){const input=$('#newalias'),value=input?.value.trim();if(!value)return false;const aliases=traitDraft[traitIndex].values[mzIndex].aliases;if(!aliases.some(alias=>C.normalize(alias)===C.normalize(value)))aliases.push(value);input.value='';return true;}

function processStageRail(active){return `<div class="process-stage-rail">${[['Подготовка ИД','IFC и график'],['Обработка системой','Работы и маппинг'],['Просмотр результата','Viewer и статусы']].map(([name,caption],index)=>`<div class="process-stage ${index===active?'active':''} ${index<active?'done':''}"><i>${index+1}</i><span><b>${name}</b><small>${caption}</small></span></div>`).join('<em>→</em>')}</div>`;}
function processVisual(type){if(type==='viewer')return `<figure class="process-visual process-visual-screenshot"><img src="/assets/status-viewer.png?v=20261104-2" alt="Статусная модель в 3D-viewer прототипа"></figure>`;const building=`<svg class="mock-building" viewBox="0 0 300 150" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2"><path d="M25 111 142 43l132 49-116 45Z"/><path d="M25 93 142 25l132 49-116 45Z"/><path d="m25 93 0 18m117-86v18m132 31v18m-116 27v18"/><path d="m63 83 96 35m-73-49 96 36m-72-50 96 36m-72-50 96 36M57 101l117-68m-82 81 117-68m-82 81 117-68"/></g><path d="m105 82 39-22 64 24-38 22Z" fill="currentColor" opacity=".24"/><path d="m105 82 65 24v22l-65-24Z" fill="currentColor" opacity=".38"/><path d="m170 106 38-22v22l-38 22Z" fill="currentColor" opacity=".55"/></svg>`;const screens={overview:`<div class="mock-overview"><div class="mock-source"><span>IFC</span><i>Параметры элементов</i><b>КФО · Корпус · Этаж</b></div><em>+</em><div class="mock-source sheet"><span>XLSX</span><i>Операции и даты</i><b>Плоский график</b></div><strong>→</strong><div class="mock-result"><img src="/assets/status-viewer.png?v=20261104-2" alt="Статусная модель в 3D-viewer"><b>Статусная модель</b></div></div>`,ifc:`<div class="mock-app"><aside><b>Настройки</b><span>КФО</span><span class="on">Корпус</span><span>Этаж</span></aside><main><div class="mock-title"><b>Настройка корпуса</b><button>Сохранить</button></div><div class="mock-rule"><small>Ключи параметров</small><p><i>1</i><span>SM_Корпус</span></p><p><i>2</i><span>Корпус</span></p><p><i>3</i><span>Building</span></p></div><div class="mock-values"><small>Допустимые значения</small><b>А</b><b>Б</b><b>В</b></div></main></div>`,schedule:`<div class="mock-sheet"><div class="mock-filebar"><b>График строительства.xlsx</b><span>Подготовка импорта</span></div><div class="mock-sheet-grid"><b>Операция</b><b>Код КФО</b><b>Корпус</b><b>Этаж</b><b>План Н</b><b>План О</b><span>Устройство стен</span><span>КФО-12</span><span>Б</span><span>03</span><span>14.09.26</span><span>28.09.26</span><span>Монтаж перекрытия</span><span>КФО-14</span><span>Б</span><span>04</span><span>29.09.26</span><span>12.10.26</span></div><div class="mock-clean"><span>Иерархия развёрнута</span><span>Лишние значения исключены</span><button>Импортировать</button></div></div>`,system:`<div class="mock-system"><section><header><span>XLSX</span><b>График</b></header><p>Операции <i>2 486</i></p><p>Работы <i>614</i></p><div class="mock-progress"><i></i></div></section><div class="mock-link"><span>КФО</span><span>Корпус</span><span>Этаж</span><b>Сопоставление</b></div><section><header><span>IFC</span><b>Модель</b></header><p>Элементы <i>5 492</i></p><p>Работы <i>608</i></p><div class="mock-progress"><i></i></div></section><footer><b>587</b><span>работ связано</span><i>21 требуют проверки</i></footer></div>`,viewer:`<div></div>`};return `<figure class="process-visual process-visual-${type}"><div class="mock-browser"><i></i><i></i><i></i><span>КСУП BIM · макет</span></div>${screens[type]}</figure>`;}
function processSlides(){return [
`${processStageRail(0)}<section class="process-slide process-overview"><div class="process-kicker">Текущий процесс</div><h3>Два источника подготавливаются отдельно, затем связываются через работу</h3><p class="process-lead">Основной объём ручных действий находится до загрузки данных в систему.</p>${processVisual('overview')}<div class="process-three"><article class="process-phase accent"><span>01</span><h4>Подготовка исходных данных</h4><div class="process-sources"><b>IFC</b><small>Параметры элементов, ключи и допустимые варианты</small><b>XLSX</b><small>Операции, КФО, локализация и даты</small></div></article><article class="process-phase"><span>02</span><h4>Обработка системой</h4><p>График и IFC обрабатываются независимо. В каждом источнике формируются работы, после чего система сопоставляет их.</p></article><article class="process-phase"><span>03</span><h4>Просмотр результата</h4><p>Связанные IFC-элементы получают статус работы на выбранную дату и отображаются во viewer.</p></article></div><div class="process-current-focus"><b>Текущий фокус</b><span>Стабилизировать подготовку IFC и графика так, чтобы система получала однозначные КФО, корпус и этаж.</span></div></section>`,
`${processStageRail(0)}<section class="process-slide"><div class="process-kicker">Подготовка ИД · IFC</div><h3>Проверить, достаточно ли данных в модели для формирования работы</h3>${processVisual('ifc')}<div class="ifc-decision"><div class="process-node source"><small>Источник</small><b>IFC-модель</b></div><div class="process-arrow">→</div><div class="process-node decision"><b>В элементах есть КФО, корпус и этаж?</b></div><div class="decision-branches"><div><span class="branch-label no">Нет</span><article><b>Получить недостающие данные</b><p>Запросить их у автора модели либо дополнить параметры вне CDE.</p></article></div><div><span class="branch-label yes">Да</span><article><b>Проверить системный справочник</b><p>Система должна знать имена параметров и варианты их значений.</p></article></div></div><div class="process-arrow down">↓</div><div class="ifc-finish"><article><small>Если правила отсутствуют</small><b>Добавить новые ключи и допустимые варианты</b><p>Системные настройки → КФО / Корпус / Этаж</p></article><div class="process-arrow">→</div><article class="result"><small>Результат подготовки</small><b>IFC готов к загрузке</b><p>Все необходимые значения читаются по действующим правилам.</p></article></div></div></section>`,
`${processStageRail(0)}<section class="process-slide"><div class="process-kicker">Подготовка ИД · График</div><h3>Развернуть иерархический график в плоскую таблицу и очистить признаки</h3>${processVisual('schedule')}<div class="schedule-flow"><article><i>1</i><small>Исходный график</small><b>Получить все операции</b><p>Сохранить исходную структуру и состав операций.</p></article><article><i>2</i><small>Извлечение</small><b>Забрать КФО и даты</b><p>Плановое и фактическое начало и окончание.</p></article><article class="script"><i>3</i><small>Скрипт дорабатывается</small><b>Развернуть иерархию</b><p>Вычленить корпус и этаж, которые сейчас скрыты в уровнях графика.</p></article><article><i>4</i><small>Решение пользователя</small><b>Назначить смысл полям</b><p>Указать, что является корпусом, а что этажом.</p></article><article><i>5</i><small>Очистка</small><b>Убрать лишние значения</b><p>Оставить допустимые КФО, корпуса и этажи.</p></article><article class="result"><i>6</i><small>Результат подготовки</small><b>Заполнить шаблон XLSX</b><p>Плоская таблица готова к импорту.</p></article></div><div class="flat-table"><b>Целевая строка</b><span>Операция</span><span>Код КФО</span><span>Корпус</span><span>Этаж</span><span>План Н</span><span>План О</span><span>Факт Н</span><span>Факт О</span></div></section>`,
`${processStageRail(1)}<section class="process-slide"><div class="process-kicker">Обработка системой</div><h3>Каждый источник формирует работы независимо</h3>${processVisual('system')}<div class="system-lanes"><article><div class="lane-head"><span>XLSX</span><b>График</b></div><ul><li>Проверка структуры и значений</li><li>Чтение операций и дат</li><li>Группировка операций по полному идентификатору</li></ul><strong>Работы графика</strong></article><article><div class="lane-head"><span>IFC</span><b>Модель</b></div><ul><li>Чтение параметров элементов</li><li>Распознавание КФО, корпуса и этажа</li><li>Группировка элементов по полному идентификатору</li></ul><strong>Работы модели</strong></article></div><div class="mapping-rule"><span>Код КФО</span><i>+</i><span>Корпус</span><i>+</i><span>Этаж</span><b>→ сопоставление работ</b></div><div class="mapping-results"><span class="linked">Связанные работы</span><span>Работы только в графике</span><span>Работы только в IFC</span><span>Неполные данные</span></div></section>`,
`${processStageRail(2)}<section class="process-slide"><div class="process-kicker">Просмотр результата</div><h3>Viewer рассчитывает состояние на выбранную дату</h3>${processVisual('viewer')}<div class="viewer-process"><article><small>1 · Дата</small><b>Пользователь выбирает дату просмотра</b><p>Календарь, ползунок или воспроизведение таймлайна.</p></article><em>→</em><article><small>2 · Расчёт</small><b>Система определяет статус операций</b><p>Плановые и фактические даты применяются в момент запроса.</p></article><em>→</em><article><small>3 · Агрегация</small><b>Операции формируют статус работы</b><p>Не начато, в работе, завершено или требует данных.</p></article><em>→</em><article class="result"><small>4 · Визуализация</small><b>IFC-элементы окрашиваются</b><p>Пользователь фильтрует статусы и управляет видимостью моделей.</p></article></div><div class="viewer-outcome"><div><b>Пользователь видит</b><span>что выполнено</span><span>что выполняется</span><span>что ещё не начато</span></div><div><b>Отдельно контролируется</b><span>IFC без КФО</span><span>несвязанные работы</span><span>неполные идентификаторы</span></div></div></section>`];}
function processPresentation(index=processSlide){const slides=processSlides();processSlide=Math.max(0,Math.min(index,slides.length-1));const previous=btn('processprev','← Назад','',processSlide===0?'disabled':''),next=processSlide===slides.length-1?btn('processclose','Закрыть','primary'):btn('processnext','Далее →','primary');showModal('process',`<div class="process-deck">${slides[processSlide]}</div>`,'Бизнес-процесс: график + IFC → статусная модель',`<div class="process-footer">${previous}<span>${processSlide+1} / ${slides.length}</span>${next}</div>`,true);}

function demoPanel(){processSlide=0;processPresentation();}
function downloadReport(){if(!importResult)return;const head=['Тип ошибки','Номер строки XLSX','Поле','Столбец XLSX','Исходное значение','Причина'];const csv='\uFEFF'+[head,...importResult.errors.map(e=>[e.type,e.row,e.field,e.col,e.value,e.reason])].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Отчёт_об_ошибках_импорта.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;const t=traitDraft?.[traitIndex];const i=Number(b.dataset.i);switch(a){
case'home':case'works':e.preventDefault();close();view='works';render();break;
case'account':accountMenu();break;
case'filters':filters();break;
case'applyfilters':query=$('#search').value;filter=$('#status-filter').value;closePopover();render();break;
case'collapseaside':$('.settings-layout').classList.toggle('aside-collapsed');break;
case'pickdate':if(canProject()){draftDate=b.dataset.date;drawCalendar();}break;
case'calprev':case'calnext':case'calprevyear':case'calnextyear':{const d=new Date(calendarMonth+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+({calprev:-1,calnext:1,calprevyear:-12,calnextyear:12}[a]));calendarMonth=d.toISOString().slice(0,7);drawCalendar();break;}
case'traits':close();if(canProject()){view='traits';render();}else{accountMenu();toast('Настройки доступны администратору');}break;
case'schedule':case'modeltab':tab=a==='schedule'?'schedule':'models';query='';filter='';onlyBim=false;expanded.clear();render();break;
case'stage':workStage=b.dataset.stage||'all';expanded.clear();render();break;
case'toggle':expanded.has(b.dataset.code)?expanded.delete(b.dataset.code):expanded.add(b.dataset.code);render();break;
case'expand':expanded=new Set((tab==='schedule'?(chosen()?C.groupOperations(chosen().ops):[]):state.ifcResult.groups).map(g=>g.code));render();break;
case'collapse':expanded.clear();render();break;
case'sort':sortAsc=sortKey===b.dataset.key?!sortAsc:true;sortKey=b.dataset.key;render();break;
case'bim':onlyBim=!onlyBim;render();break;
case'clearsearch':query='';render();break;
case'close':close();break;case'closetoast':$('#toast').classList.remove('show');break;
case'versions':versions();break;
case'chooseversion':selected=Number(b.dataset.n);expanded.clear();close();render();break;
case'archive':if(canProject()){const n=Number(b.dataset.n);showModal('archive',`<p>Версия <b>v${n}</b> будет архивирована. Её можно будет восстановить из перечня версий.</p><p class="hint">Архивирование и восстановление добавлены для прототипа; в MVP этих действий не будет.</p>`,'Архивировать версию?',btn('versions','Отменить')+btn('confirmarchive','Архивировать','danger',`data-n="${n}"`));}break;
case'confirmarchive':if(canProject()){state.versions.find(v=>v.n===Number(b.dataset.n)).archived=true;if(selected===Number(b.dataset.n))selected=current()?.n;persist();render();versions();toast('Версия архивирована');}break;
case'restore':if(canProject()){state.versions.find(v=>v.n===Number(b.dataset.n)).archived=false;persist();render();versions();toast('Версия восстановлена');}break;
case'date':editDate();break;
case'savedate':{if(!canProject())break;const v=chosen();const max=C.max(v.ops.flatMap(o=>[o.fs,o.ff]));if(!draftDate||max&&draftDate<max)break;v.date=draftDate;persist();close();render();toast('Отчётная дата изменена');break;}
case'import':importModal();break;case'demoload':demoLoad();break;case'runimport':runImport();break;case'downloadreport':downloadReport();break;
case'open3d':openViewer();break;case'models':modelSettings();break;case'refreshmodels':await refreshModels();break;case'savemodels':applyModels();break;
case'clearcache':showModal('clearcache','<p>Будут удалены сохранённые SHA-256 и результаты обработки свойств и геометрии IFC. Выбранные модели пересоберутся при следующем использовании.</p><p class="hint">Это служебное действие существует только в прототипе и не входит в MVP.</p>','Очистить прототипный хэш?',btn('models','Отменить')+btn('confirmclearcache','Очистить','danger'));break;
case'confirmclearcache':await clearPrototypeCache();break;
case'edittrait':if(canProject())startTrait(b.dataset.id);break;
case'traitstep1':if(step===2)commitPendingAlias();step=1;editTrait();break;case'traitstep2':{commitPendingKey();const keyErrors=C.validateTraits(traitDraft).filter(error=>error.toLowerCase().includes('ключ'));if(keyErrors.length){editTrait();break;}step=2;editTrait();break;}
case'addkey':{const input=$('#newkey');if(!input.value.trim()){input.focus();break;}commitPendingKey();editTrait();$('#newkey').focus();break;}
case'delkey':t.keys.splice(i,1);editTrait();break;
case'key-up':case'key-down':{const j=a==='key-up'?i-1:i+1;[t.keys[i],t.keys[j]]=[t.keys[j],t.keys[i]];editTrait();break;}
case'addmz':commitPendingAlias();t.values.push({name:'',aliases:[]});mzIndex=t.values.length-1;editTrait();$('#mzname')?.focus();break;
case'delmz':t.values.splice(i,1);mzIndex=Math.max(0,Math.min(mzIndex,t.values.length-1));editTrait();break;
case'selectmz':commitPendingAlias();mzIndex=i;editTrait();break;
case'addalias':{const input=$('#newalias');if(!input.value.trim()){input.focus();break;}t.values[mzIndex].aliases.push(input.value);editTrait();$('#newalias').focus();break;}
case'delalias':t.values[mzIndex].aliases.splice(i,1);editTrait();break;
case'savetrait':{commitPendingAlias();const errors=C.validateTraits(traitDraft);if(errors.length){validateTraitUi();break;}const previous=clone(state.traits),changed=JSON.stringify(previous)!==JSON.stringify(traitDraft);state.traits=clone(traitDraft);if(changed&&state.models.some(m=>m.selected!==null))state.noticeTraits=true;if(persistTraits()&&persist()){close();render();toast('Настройки признаков сохранены и проверены');}else{state.traits=previous;$('#trait-errors').innerHTML='<p>Браузер не подтвердил сохранение. Настройки не закрыты — попробуйте ещё раз.</p>';}break;}
case'demo':demoPanel();break;case'processdeck':processSlide=0;processPresentation();break;case'processprev':processPresentation(processSlide-1);break;case'processnext':processPresentation(processSlide+1);break;case'processclose':close();break;
case'scenarioempty':state.versions.forEach(v=>v.archived=true);selected=null;state.models.forEach(m=>m.selected=null);state.ifcResult=C.groupModels(state.models,state.traits);state.noticeModels=false;state.noticeTraits=false;view='works';tab='schedule';persist();close();render();break;
case'scenariopartial':case'scenariofatal':role='admin';view='works';render();importModal();demoLoad(a==='scenariofatal'?'fatal':'partial');break;
case'scenariotraits':state.noticeTraits=true;persist();close();view='works';render();break;
case'scenariomodel':{const m=state.models.find(m=>m.selected!==null)||state.models[0];if(m.selected===null)m.selected=m.versions.find(v=>v.processed).n;const n=Math.max(...m.versions.map(v=>v.n))+1;m.versions.unshift({n,processed:true});state.noticeModels=true;persist();close();view='works';render();break;}
case'reset':state=seed();selected=3;view='works';tab='schedule';query='';filter='';onlyBim=false;expanded.clear();persistTraits();persist();close();render();toast('Демонстрационные данные восстановлены');break;
}});
document.addEventListener('click',e=>{if(popover&&!e.target.closest('.control-anchor,.account-anchor,.account,.header-icon,[data-action=traits]'))closePopover();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal&&!modelProcessing)close();else if(!modal)closePopover();}if(e.key==='Tab'&&modal){const els=[...$('#overlay').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(e=>!e.hidden);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
render();
syncIfcCatalog().then(loaded=>{if(loaded)hydrateSelectedIfc();});
})();
